29	  <style>
30	    :root {
31	      color-scheme: light dark;
32	      --bg: #ffffff;
33	      --fg: #1a1a1a;
34	      --muted: #555;
35	      --accent: #2563eb;
36	      --border: #e5e7eb;
37	    }
38	
39	    @media (prefers-color-scheme: dark) {
40	      :root {
41	        --bg: #111214;
42	        --fg: #e8e8e8;
43	        --muted: #aaa;
44	        --accent: #60a5fa;
45	        --border: #2a2b2e;
46	      }
47	    }
48	
49	    :root[data-theme="light"] {
50	      color-scheme: light;
51	      --bg: #ffffff;
52	      --fg: #1a1a1a;
53	      --muted: #555;
54	      --accent: #2563eb;
55	      --border: #e5e7eb;
56	    }
57	
58	    :root[data-theme="dark"] {
59	      color-scheme: dark;
60	      --bg: #111214;
61	      --fg: #e8e8e8;
62	      --muted: #aaa;
63	      --accent: #60a5fa;
64	      --border: #2a2b2e;
65	    }
66	
67	    * {
68	      box-sizing: border-box;
69	    }
70	
71	    html {
72	      scroll-behavior: smooth;
73	    }
74	
75	    @media (prefers-reduced-motion: reduce) {
76	      html {
77	        scroll-behavior: auto;
78	      }
79	    }
80	
81	    ::selection {
82	      background: var(--accent);
83	      color: var(--bg);
84	    }
85	
86	    body {
87	      font-family: system-ui, -apple-system, sans-serif;
88	      max-width: 40rem;
89	      margin: 3rem auto;
90	      padding: 0 1rem;
91	      line-height: 1.6;
92	      color: var(--fg);
93	      background: var(--bg);
94	    }
95	
96	    @media (max-width: 30rem) {
97	      body {
98	        margin: 1.5rem auto;
99	      }
100	    }
101	
102	    h1 {
103	      font-size: clamp(1.75rem, 5vw, 2.5rem);
104	      margin-bottom: 0.5rem;
105	    }
106	
107	    p {
108	      color: var(--muted);
109	      max-width: 34rem;
110	    }
111	
112	    a {
113	      color: var(--accent);
114	      transition: opacity 0.15s ease;
115	    }
116	
117	    a:hover {
118	      opacity: 0.8;
119	    }
120	
121	    a:focus-visible,
122	    button:focus-visible {
123	      outline: 2px solid var(--accent);
124	      outline-offset: 2px;
125	    }
126	
127	    .skip-link {
128	      position: absolute;
129	      left: -9999px;
130	      top: 0;
131	      background: var(--accent);
132	      color: var(--bg);
133	      padding: 0.5rem 1rem;
134	      border-radius: 0.25rem;
135	      z-index: 10;
136	    }
137	
138	    .skip-link:focus {
139	      left: 1rem;
140	      top: 1rem;
141	    }
142	
143	    main:focus {
144	      outline: none;
145	    }
146	
147	    nav {
148	      display: flex;
149	      align-items: center;
150	      gap: 1rem;
151	      margin-bottom: 2rem;
152	    }
153	
154	    nav ul {
155	      display: flex;
156	      flex-wrap: wrap;
157	      gap: 1rem;
158	      list-style: none;
159	      padding: 0;
160	      margin: 0;
161	    }
162	
163	    nav a {
164	      text-decoration: none;
165	      font-weight: 500;
166	      opacity: 1;
167	    }
168	
169	    nav a:hover {
170	      text-decoration: underline;
171	    }
172	
173	    nav a[aria-current="page"] {
174	      text-decoration: underline;
175	      color: var(--fg);
176	      font-weight: 700;
177	    }
178	
179	    .theme-toggle {
180	      margin-left: auto;
181	      background: none;
182	      border: 1px solid var(--border);
183	      color: var(--fg);
184	      border-radius: 0.375rem;
185	      padding: 0.25rem 0.6rem;
186	      font: inherit;
187	      font-size: 0.875rem;
188	      cursor: pointer;
189	    }
190	
