209	      margin-top: 3rem;
210	      padding-top: 1.5rem;
211	      border-top: 1px solid var(--border);
212	      font-size: 0.875rem;
213	      color: var(--muted);
214	    }
215	
216	    @media print {
217	      .skip-link,
218	      nav {
219	        display: none;
220	      }
221	    }
222	  </style>
223	  <script>
224	    (function () {
225	      const stored = localStorage.getItem('theme');
226	      if (stored === 'light' || stored === 'dark') {
227	        document.documentElement.dataset.theme = stored;
228	      }
229	    })();
230	  </script>
231	</head>
232	<body>
233	  <a class="skip-link" href="#main">Skip to content</a>
234	  <nav aria-label="Primary">
235	    <ul>
236	      <li><a href="#home" data-nav-link aria-current="page">Home</a></li>
237	      <li><a href="#about" data-nav-link>About</a></li>
238	      <li><a href="#contact" data-nav-link>Contact</a></li>
239	    </ul>
240	    <button type="button" class="theme-toggle" id="theme-toggle" aria-label="Toggle color theme" aria-pressed="false"><span aria-hidden="true">🌙</span></button>
241	  </nav>
242	  <main id="main" tabindex="-1">
243	    <section id="home" aria-labelledby="home-heading">
244	      <h1 id="home-heading">My Page</h1>
245	      <p>Welcome. This page is a starting point — replace this text with your own content.</p>
246	    </section>
247	
248	    <section id="about" aria-labelledby="about-heading">
249	      <h2 id="about-heading">About</h2>
250	      <p>Add a short description of what this page or project is about here.</p>
251	    </section>
252	
253	    <section id="contact" aria-labelledby="contact-heading">
254	      <h2 id="contact-heading">Contact</h2>
255	      <p>Reach out at <a href="mailto:hello@example.com">hello@example.com</a>.</p>
256	    </section>
257	  </main>
258	  <footer>
259	    <p>&copy; <span id="year">2026</span> My Page. All rights reserved.</p>
260	  </footer>
261	  <script>
262	    const yearEl = document.getElementById('year');
263	    if (yearEl) yearEl.textContent = String(new Date().getFullYear());
264	
265	    const themeToggle = document.getElementById('theme-toggle');
266	    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
267	
268	    const currentTheme = () =>
269	      document.documentElement.dataset.theme || (prefersDark.matches ? 'dark' : 'light');
270	
271	    const updateToggleLabel = () => {
272	      const isDark = currentTheme() === 'dark';
273	      themeToggle.querySelector('span').textContent = isDark ? '☀️' : '🌙';
274	      themeToggle.setAttribute('aria-pressed', String(isDark));
275	    };
276	
277	    updateToggleLabel();
278	
279	    themeToggle.addEventListener('click', () => {
280	      const next = currentTheme() === 'dark' ? 'light' : 'dark';
281	      document.documentElement.dataset.theme = next;
282	      localStorage.setItem('theme', next);
283	      updateToggleLabel();
284	    });
285	
286	    const navLinks = document.querySelectorAll('[data-nav-link]');
287	    const sections = [...navLinks]
288	      .map(link => document.querySelector(link.getAttribute('href')))
289	      .filter(Boolean);
290	
291	    const setActive = (id) => {
292	      navLinks.forEach(link => {
293	        if (link.getAttribute('href') === `#${id}`) {
294	          link.setAttribute('aria-current', 'page');
295	        } else {
296	          link.removeAttribute('aria-current');
297	        }
298	      });
299	    };
300	
301	    setActive(sections[0]?.id);
302	
303	    navLinks.forEach(link => {
304	      link.addEventListener('click', () => setActive(link.getAttribute('href').slice(1)));
305	    });
306	
307	    if ('IntersectionObserver' in window) {
308	      const observer = new IntersectionObserver((entries) => {
309	        const visible = entries
310	          .filter(entry => entry.isIntersecting)
311	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
312	        if (visible) setActive(visible.target.id);
313	      }, { rootMargin: '-40% 0px -50% 0px' });
314	      sections.forEach(section => section && observer.observe(section));
315	    }
316	  </script>
317	</body>
318	</html>
